{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C05"],
      "claim": "Spiramycin, a 16-membered macrolide with a dimethylamino sugar and a neutral sugar, has an absolute oral bioavailability of 33% in healthy volunteers, supporting F >= 20% for the structurally similar query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Rosaramicin, another 16-membered macrolide, has an absolute oral bioavailability of 39% (range 27-53%) after oral tablet dosing, supporting F >= 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Clarithromycin, a macrolide antibiotic, has an absolute oral bioavailability of 55% at a 500 mg oral dose, supporting the pattern that macrolides can achieve F well above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Dirithromycin, a macrolide prodrug, has an absolute oral bioavailability of about 10%, but its prodrug nature and 14-membered ring make it less transferable to the 16-membered query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C39"],
      "claim": "EM574, an erythromycin derivative, has an estimated oral bioavailability of about 2% due to extremely high oral clearance, but this is not representative of typical 16-membered macrolides like the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a 16-membered macrolide structurally closest to spiramycin and rosaramicin, both with absolute oral bioavailability of 33-39%, clearly above the 20% threshold. Low-bioavailability macrolide analogues are less structurally transferable, so the evidence supports a high prediction.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability value for the query molecule itself is provided.",
    "Tylosin-class macrolides are primarily veterinary drugs; human absolute bioavailability data may be limited or species-dependent.",
    "Formulation and dose effects can alter oral bioavailability, and the retrieved records use different formulations and doses."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

